from pathlib import Path

# -------- index.html --------
p=Path('index.html')
s=p.read_text(encoding='utf-8')

s=s.replace('⚾ · v5.7.0</div>','⚾ · v5.8.0</div>',1)
s=s.replace('version:"5.7.0",\n    backupSchema:2,','version:"5.8.0",\n    backupSchema:2,',1)

css='''\n/* v5.8.0 — representative card photos */\n.card-photo-panel{margin:12px 0 14px;border:1px solid var(--line);border-radius:18px;background:rgba(255,255,255,.035);padding:13px}\n.card-photo-panel[hidden]{display:none}\n.card-photo-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;margin-bottom:10px}\n.card-photo-title{font-size:16px;font-weight:950;margin-top:2px}\n.card-photo-sub{font-size:10px;color:var(--muted);line-height:1.45;margin-top:3px}\n.card-photo-frame{width:min(420px,100%);margin:0 auto;border-radius:16px;overflow:hidden;border:1px solid rgba(230,189,99,.36);background:#071c16;box-shadow:0 12px 26px rgba(0,0,0,.24)}\n.card-photo-frame[hidden]{display:none}\n.card-photo-frame button{display:block;width:100%;padding:0;border:0;background:transparent;min-height:0;border-radius:0}\n.card-photo-frame img{display:block;width:100%;max-height:590px;object-fit:contain;background:#071c16}\n.card-photo-empty{min-height:174px;display:grid;place-items:center;text-align:center;border:1px dashed rgba(230,189,99,.34);border-radius:15px;background:rgba(230,189,99,.035);padding:22px 14px}\n.card-photo-empty[hidden]{display:none}\n.card-photo-empty-icon{font-size:34px}\n.card-photo-empty strong{display:block;font-size:14px;margin-top:7px}\n.card-photo-empty span{display:block;font-size:10px;color:var(--muted);line-height:1.45;margin-top:4px}\n.card-photo-actions{display:grid;grid-template-columns:1fr 1fr auto;gap:8px;margin-top:10px}\n.card-photo-actions button{min-height:43px;font-size:10px;padding:8px 10px}\n.card-photo-status{font-size:9.5px;color:var(--muted);line-height:1.45;margin-top:8px}\n.card-photo-status.ok{color:#9ce8bb}.card-photo-status.warn{color:#f4d58a}.card-photo-status.bad{color:#ffaaa2}\n.card-photo-lightbox{position:fixed;inset:0;z-index:1300;background:rgba(0,0,0,.91);display:grid;place-items:center;padding:calc(18px + env(safe-area-inset-top)) 14px calc(18px + env(safe-area-inset-bottom))}\n.card-photo-lightbox[hidden]{display:none}\n.card-photo-lightbox-inner{position:relative;width:min(760px,100%);height:min(90vh,900px);display:grid;place-items:center}\n.card-photo-lightbox img{max-width:100%;max-height:100%;object-fit:contain;border-radius:14px;box-shadow:0 18px 60px rgba(0,0,0,.55)}\n.card-photo-lightbox-close{position:absolute;right:0;top:0;z-index:2;width:46px;height:46px;border-radius:999px;border:1px solid rgba(255,255,255,.28);background:rgba(0,0,0,.72);color:#fff;font-size:22px;font-weight:900}\n@media(max-width:620px){\n  .card-photo-panel{padding:11px}\n  .card-photo-actions{grid-template-columns:1fr 1fr}.card-photo-actions .danger{grid-column:1/-1}\n  .card-photo-frame img{max-height:68vh}\n}\n'''
needle='\n/* v5.5.0 — mobile / navigation polish */'
assert needle in s
s=s.replace(needle,css+needle,1)

markup='''\n\n      <div class="card-photo-panel" id="cardPhotoPanel" hidden>\n        <div class="card-photo-head">\n          <div>\n            <div class="section-eyebrow">📷 MY CARD PHOTO</div>\n            <div class="card-photo-title">Your actual representative card</div>\n            <div class="card-photo-sub">Take a photo on your phone or choose one from your library. Scout shrinks it before saving it privately to your cloud storage.</div>\n          </div>\n        </div>\n        <div class="card-photo-frame" id="cardPhotoFrame" hidden>\n          <button type="button" id="cardPhotoImageButton" aria-label="Enlarge card photo"><img id="cardPhotoImage" alt=""></button>\n        </div>\n        <div class="card-photo-empty" id="cardPhotoEmpty">\n          <div><div class="card-photo-empty-icon">🖼️</div><strong>No photo saved yet</strong><span>Add the actual card you use to represent this Hall of Famer.</span></div>\n        </div>\n        <div class="card-photo-actions">\n          <button type="button" class="secondary" id="cardPhotoTakeBtn">📷 TAKE PHOTO</button>\n          <button type="button" class="ghost" id="cardPhotoChooseBtn">🖼️ CHOOSE PHOTO</button>\n          <button type="button" class="danger" id="cardPhotoRemoveBtn" hidden>REMOVE</button>\n        </div>\n        <div class="card-photo-status" id="cardPhotoStatus"></div>\n        <input id="cardPhotoCameraInput" type="file" accept="image/*" capture="environment" hidden>\n        <input id="cardPhotoLibraryInput" type="file" accept="image/*" hidden>\n      </div>\n'''
needle='''      <div class="card-stage" id="cardStage">'''
assert needle in s
s=s.replace(needle,markup+'\n'+needle,1)

lightbox='''\n<div class="card-photo-lightbox" id="cardPhotoLightbox" role="dialog" aria-modal="true" aria-label="Card photo" hidden>\n  <div class="card-photo-lightbox-inner">\n    <button type="button" class="card-photo-lightbox-close" id="cardPhotoLightboxClose" aria-label="Close photo">×</button>\n    <img id="cardPhotoLightboxImage" alt="">\n  </div>\n</div>\n'''
needle='<div class="toast" id="toast" role="status" aria-live="polite"></div>'
assert needle in s
s=s.replace(needle,lightbox+needle,1)

needle='<script src="shopping-report.js"></script>'
assert needle in s
s=s.replace(needle,'<script src="card-photo.js"></script>\n'+needle,1)

needle='''  $("undoRemoveBtn").hidden=!(lastRemovedCard&&lastRemovedCard.name===p.name&&!p.owned);\n  showScreen("detailScreen");'''
assert needle in s
s=s.replace(needle,'''  $("undoRemoveBtn").hidden=!(lastRemovedCard&&lastRemovedCard.name===p.name&&!p.owned);\n  if(window.ScoutCardPhotos)ScoutCardPhotos.showPlayer(p);\n  showScreen("detailScreen");''',1)

needle='''loadPricingConfig();\nrenderRecentSearches();'''
assert needle in s
s=s.replace(needle,'''if(window.ScoutCardPhotos)ScoutCardPhotos.init({getConfig:pricingConfig,toast});\nloadPricingConfig();\nrenderRecentSearches();''',1)

p.write_text(s,encoding='utf-8')

# -------- src/index.js Worker --------
p=Path('src/index.js')
w=p.read_text(encoding='utf-8')
w=w.replace('const VERSION = "3.25.1";','const VERSION = "3.26.0";',1)
w=w.replace('const COLLECTION_MAX_PLAYERS = 500;','''const COLLECTION_MAX_PLAYERS = 500;\nconst CARD_PHOTO_PREFIX = "card-photo:v1:";\nconst CARD_PHOTO_MAX_BYTES = 1200 * 1024;\nconst CARD_PHOTO_TYPES = new Set(["image/jpeg", "image/png", "image/webp"]);''',1)
w=w.replace('"Access-Control-Allow-Methods": "GET,POST,OPTIONS",','"Access-Control-Allow-Methods": "GET,POST,DELETE,OPTIONS",',1)
w=w.replace('"Access-Control-Allow-Headers": "Content-Type,X-Scout-Key",','''"Access-Control-Allow-Headers": "Content-Type,X-Scout-Key,X-Scout-Card-Fingerprint",\n      "Access-Control-Expose-Headers": "X-Scout-Photo-Fingerprint,X-Scout-Photo-Updated-At",''',1)

route='''\n\n    if (url.pathname === "/card-photo" && ["GET", "POST", "DELETE"].includes(request.method)) {\n      const supplied = request.headers.get("X-Scout-Key") || "";\n      if (!env.SCOUT_ACCESS_KEY || supplied !== env.SCOUT_ACCESS_KEY) {\n        return json({ ok: false, error: "unauthorized", message: "Scout access key rejected." }, 401, cors);\n      }\n      if (!env.SCOUT_DATA) {\n        return json({ ok: false, error: "cloud_storage_not_configured", message: "SCOUT_DATA KV binding is not configured on the Worker." }, 503, cors);\n      }\n      const player = normalizeCardPhotoPlayer(url.searchParams.get("player"));\n      if (!player) {\n        return json({ ok: false, error: "invalid_player", message: "Scout needs a valid Hall of Famer name for the photo." }, 400, cors);\n      }\n      const key = cardPhotoKey(player);\n\n      if (request.method === "GET") {\n        try {\n          const stored = await env.SCOUT_DATA.getWithMetadata(key, { type: "arrayBuffer" });\n          if (!stored?.value) return json({ ok: false, error: "photo_not_found", message: "No representative card photo is saved for this player." }, 404, cors);\n          const metadata = stored.metadata && typeof stored.metadata === "object" ? stored.metadata : {};\n          return new Response(stored.value, {\n            status: 200,\n            headers: {\n              ...cors,\n              "Content-Type": CARD_PHOTO_TYPES.has(metadata.contentType) ? metadata.contentType : "image/jpeg",\n              "Cache-Control": "private, max-age=300",\n              "X-Scout-Photo-Fingerprint": String(metadata.fingerprint || ""),\n              "X-Scout-Photo-Updated-At": String(metadata.updatedAt || "")\n            }\n          });\n        } catch (err) {\n          console.error(err);\n          return json({ ok: false, error: "photo_load_failed", message: "Scout could not load that card photo." }, 502, cors);\n        }\n      }\n\n      if (request.method === "DELETE") {\n        try {\n          await env.SCOUT_DATA.delete(key);\n          return json({ ok: true, version: VERSION, player }, 200, cors);\n        } catch (err) {\n          console.error(err);\n          return json({ ok: false, error: "photo_delete_failed", message: "Scout could not remove that card photo." }, 502, cors);\n        }\n      }\n\n      const contentType = String(request.headers.get("Content-Type") || "").split(";")[0].trim().toLowerCase();\n      if (!CARD_PHOTO_TYPES.has(contentType)) {\n        return json({ ok: false, error: "invalid_photo_type", message: "Scout accepts JPEG, PNG, or WebP card photos." }, 415, cors);\n      }\n      let bytes;\n      try { bytes = await request.arrayBuffer(); }\n      catch { return json({ ok: false, error: "photo_read_failed", message: "Scout could not read that card photo." }, 400, cors); }\n      if (!bytes.byteLength || bytes.byteLength > CARD_PHOTO_MAX_BYTES) {\n        return json({ ok: false, error: "photo_too_large", message: "That card photo is too large after compression. Please try another photo." }, 413, cors);\n      }\n      const fingerprint = normalizeCardPhotoFingerprint(request.headers.get("X-Scout-Card-Fingerprint"));\n      const updatedAt = new Date().toISOString();\n      try {\n        await env.SCOUT_DATA.put(key, bytes, { metadata: { contentType, fingerprint, updatedAt, bytes: bytes.byteLength } });\n        return json({ ok: true, version: VERSION, player, updatedAt, bytes: bytes.byteLength }, 200, cors);\n      } catch (err) {\n        console.error(err);\n        return json({ ok: false, error: "photo_save_failed", message: "Scout could not save that card photo." }, 502, cors);\n      }\n    }\n'''
needle='''\n\n    if (url.pathname === "/collection/load" && request.method === "GET") {'''
assert needle in w
w=w.replace(needle,route+needle,1)

helpers='''\nfunction normalizeCardPhotoPlayer(value) {\n  const player = String(value || "").trim().replace(/\\s+/g, " ");\n  return player.length >= 2 && player.length <= 100 ? player : "";\n}\n\nfunction normalizeCardPhotoFingerprint(value) {\n  const fp = String(value || "").trim().toLowerCase();\n  return /^[a-f0-9]{8,64}$/.test(fp) ? fp : "";\n}\n\nfunction cardPhotoKey(player) {\n  return CARD_PHOTO_PREFIX + encodeURIComponent(String(player || "").trim().toLowerCase());\n}\n\n'''
needle='''function validateCard(c) {'''
assert needle in w
w=w.replace(needle,helpers+needle,1)
p.write_text(w,encoding='utf-8')

# -------- tests --------
t=Path('tests/offline-shopping-report.test.cjs')
ts=t.read_text(encoding='utf-8').replace(r'/v5\.7\.0/',r'/v5\.8\.0/')
t.write_text(ts,encoding='utf-8')

photo_test='''const assert=require("node:assert/strict");\nconst fs=require("node:fs");\nconst photos=require("../card-photo.js");\nconst html=fs.readFileSync("index.html","utf8");\nconst worker=fs.readFileSync("src/index.js","utf8");\n\nassert.equal(photos.fingerprintForPlayer({owned:false,name:"Sandy Koufax"}),"");\nconst fp=photos.fingerprintForPlayer({owned:true,name:"Sandy Koufax",cardYear:1965,set:"Topps",cardNum:"300",grader:"PSA",gradeCondition:"6"});\nassert.match(fp,/^[a-f0-9]{8}$/);\nassert.equal(fp,photos.fingerprintForPlayer({owned:true,name:"Sandy Koufax",cardYear:1965,set:"Topps",cardNum:"300",grader:"PSA",gradeCondition:"6"}));\nassert.notEqual(fp,photos.fingerprintForPlayer({owned:true,name:"Sandy Koufax",cardYear:1966,set:"Topps",cardNum:"100",grader:"PSA",gradeCondition:"6"}));\n\nassert.match(html,/v5\\.8\\.0/);\nassert.match(html,/id="cardPhotoPanel"/);\nassert.match(html,/id="cardPhotoCameraInput"[^>]*capture="environment"/);\nassert.match(html,/id="cardPhotoLibraryInput"/);\nassert.match(html,/<script src="card-photo\\.js"><\\/script>/);\nassert.match(html,/ScoutCardPhotos\\.init\\(\\{getConfig:pricingConfig,toast\\}\\)/);\nassert.match(html,/ScoutCardPhotos\\.showPlayer\\(p\\)/);\nassert.match(html,/id="cardPhotoLightbox"/);\n\nassert.match(worker,/const VERSION = "3\\.26\\.0"/);\nassert.match(worker,/CARD_PHOTO_PREFIX/);\nassert.match(worker,/CARD_PHOTO_MAX_BYTES = 1200 \* 1024/);\nassert.match(worker,/url\\.pathname === "\\/card-photo"/);\nassert.match(worker,/\\["GET", "POST", "DELETE"\\]/);\nassert.match(worker,/getWithMetadata\\(key, \\{ type: "arrayBuffer" \\}\\)/);\nassert.match(worker,/SCOUT_DATA\\.put\\(key, bytes, \\{ metadata:/);\nassert.match(worker,/SCOUT_DATA\\.delete\\(key\\)/);\nassert.match(worker,/X-Scout-Photo-Fingerprint/);\nassert.match(worker,/X-Scout-Card-Fingerprint/);\nassert.match(worker,/Access-Control-Allow-Methods.*DELETE/);\n\nconst client=fs.readFileSync("card-photo.js","utf8");\nassert.match(client,/MAX_DIMENSION=1600/);\nassert.match(client,/TARGET_BYTES=900\\*1024/);\nassert.match(client,/indexedDB/);\nassert.match(client,/canvas\\.toBlob/);\nassert.match(client,/method:"POST"/);\nassert.match(client,/method:"DELETE"/);\nassert.match(client,/previous representative card/);\nconsole.log("Representative card photo tests passed.");\n'''
Path('tests/card-photos.test.cjs').write_text(photo_test,encoding='utf-8')
